begin;
set local search_path=public,extensions;
select no_plan();
-- @command-fixtures
select ok(to_regclass('private.challenge_rehearsals') is null,'fixed bindings have been removed');
select ok(not has_table_privilege('authenticated','private.rehearsal_publication_policies','SELECT'),'players cannot read policies');
select ok(not has_table_privilege('service_role','private.rehearsal_publication_policies','INSERT'),'server uses guarded policy command');
select ok(not has_function_privilege('authenticated','private.read_player_rehearsal_template(text,uuid)','EXECUTE'),'templates are never exposed through PostgREST');
select ok(not has_function_privilege('service_role','private.rehearsal_template(uuid)','EXECUTE'),'raw structural helper is private');
select is((select count(*) from private.question_versions where difficulty<>'medium'),0::bigint,'existing questions default to medium');
select test_support.as_actor('member');
set local role service_role;
select is(private.read_player_rehearsal_template('commands-flash',test_support.id('sc-flash'))->>'enabled','true','practice needs no binding and defaults to enabled');
select is(private.read_player_rehearsal_template('commands-flash',test_support.id('sc-flash'))#>>'{template,questions,0,difficulty}','medium','official difficulty is projected');
select ok(private.read_player_rehearsal_template('commands-flash',test_support.id('sc-flash'))::text not like '%solutionPayload%','structural read has no official solutions');
select throws_ok($$select private.read_editorial_rehearsal_template(test_support.id('cv-flash'))$$,'42501','not_authorized','member cannot inspect editorial templates');
select throws_ok($$select private.set_rehearsal_publication_policy('{}')$$,'42501','not_authorized','member cannot change publication policy');
reset role;
select is((select count(*) from public.attempts),0::bigint,'reading templates creates no attempts');
insert into public.scheduled_challenges(id,season_id,challenge_version_id,number,status,opens_at,closes_at)
values(test_support.id('sc-rehearsal-future'),test_support.id('season-flash'),test_support.id('cv-flash'),3,'scheduled',now()+interval '25 hours',now()+interval '26 hours');
select ok(private.read_player_rehearsal_template('commands-flash',test_support.id('sc-rehearsal-future')) is not null,'practice is available before competitive opening without an association');
update public.room_memberships set status='removed',ended_at=now() where room_id=test_support.id('room-flash') and player_id=test_support.id('member');
select is(private.read_player_rehearsal_template('commands-flash',test_support.id('sc-rehearsal-future')),null::jsonb,'membership loss denies direct access');
update public.room_memberships set status='active',ended_at=null where room_id=test_support.id('room-flash') and player_id=test_support.id('member');
update public.rooms set status='deleted',deleted_at=now() where id=test_support.id('room-flash');
select is(private.read_player_rehearsal_template('commands-flash',test_support.id('sc-rehearsal-future')),null::jsonb,'inactive room denies access');
update public.rooms set status='active',deleted_at=null where id=test_support.id('room-flash');
update public.scheduled_challenges set status='closed' where id=test_support.id('sc-rehearsal-future');
select is(private.read_player_rehearsal_template('commands-flash',test_support.id('sc-rehearsal-future')),null::jsonb,'closed publication denies access');
update public.scheduled_challenges set status='cancelled',cancelled_at=now() where id=test_support.id('sc-rehearsal-future');
select is(private.read_player_rehearsal_template('commands-flash',test_support.id('sc-rehearsal-future')),null::jsonb,'cancelled publication denies access');
select test_support.as_actor('spectator');
select is(private.read_player_rehearsal_template('commands-flash',test_support.id('sc-flash')),null::jsonb,'spectator is denied');
select test_support.as_actor('outsider');
select is(private.read_player_rehearsal_template('commands-flash',test_support.id('sc-flash')),null::jsonb,'outsider is denied');
select test_support.as_actor('superadmin');
select throws_ok($$select private.set_rehearsal_publication_policy(jsonb_build_object('publicationId',test_support.id('sc-flash'),'enabled',false,'expectedUpdatedAt',null,'idempotencyKey','invalid-policy-reason','reason',''))$$,'22023','invalid_command','policy changes require a reason');
create temp table rehearsal_input(body jsonb);
grant select on rehearsal_input to service_role;
insert into rehearsal_input values(jsonb_build_object('publicationId',test_support.id('sc-flash'),'enabled',false,'expectedUpdatedAt',null,'idempotencyKey','disable-practice-test','reason','Revisión del banco'));
set local role service_role;
select is(private.set_rehearsal_publication_policy((select body from rehearsal_input))->>'enabled','false','admin may disable a published practice');
select is(private.set_rehearsal_publication_policy((select body from rehearsal_input))->>'enabled','false','exact replay is idempotent');
select throws_ok($$select private.set_rehearsal_publication_policy((select body from rehearsal_input)||'{"enabled":true}')$$,'40001','idempotency_conflict','cannot reuse key with another input');
select throws_ok($$select private.set_rehearsal_publication_policy((select body from rehearsal_input)||'{"idempotencyKey":"stale-policy-update"}')$$,'40001','content_conflict','stale editor cannot overwrite policy');
reset role;
select is((select count(*) from private.audit_log where action='set_rehearsal_publication_policy'),1::bigint,'one audit event per mutation');
select test_support.as_actor('member');
select is(private.read_player_rehearsal_template('commands-flash',test_support.id('sc-flash'))->>'enabled','false','disabled and unauthorized are distinguishable');
select test_support.as_actor('superadmin');
select private.set_rehearsal_publication_policy(jsonb_build_object('publicationId',test_support.id('sc-flash'),'enabled',true,'expectedUpdatedAt',(select updated_at from private.rehearsal_publication_policies where scheduled_challenge_id=test_support.id('sc-flash')),'idempotencyKey','reenable-practice-test','reason','Revisión completada'));
select is(private.read_editorial_rehearsal_template(test_support.id('cv-narrative')),null::jsonb,'narrative is outside dynamic practice');
select throws_ok($$update private.question_versions set difficulty='hard' where id=test_support.id('qv-normal')$$,'P0001','Published content is immutable; create another version','difficulty is immutable after publishing');
select test_support.as_actor('member');
set local role service_role;
select test_support.run('start_attempt',jsonb_build_object('scheduledChallengeId',test_support.id('sc-flash'),'sessionToken',repeat('r',40)));
select is(private.read_player_rehearsal_template('commands-flash',test_support.id('sc-flash')),null::jsonb,'official attempt prevents another practice');
select test_support.run('abandon_attempt');
select is(private.read_player_rehearsal_template('commands-flash',test_support.id('sc-flash')),null::jsonb,'terminal attempt also prevents practice');
reset role;
select * from finish();
rollback;
